    "title": "Behind the project: 1900 Broadway",
    "summary": "Behind 1900 Broadway were new, unconventional decisions and workflows that continue to shape our work today. Discover the story behind the project.",
    "cover": "https://cdn.prod.website-files.com/686d0fd099ee65617e107e24/6aea0b09861681cd1a3b41c0_Project%20cover%20(3).jpg",
    "accentColor": "",
