    "cover": "https://cdn.prod.website-files.com/686d0fd099ee65617e107e24/695263c8d330cf7bf1f539d4_%D0%94%D0%B8%D0%B7%D0%B0%D0%B8%CC%86%D0%BD%20%D0%B1%D0%B5%D0%B7%20%D0%BD%D0%B0%D0%B7%D0%B2%D0%B8.jpg",
