    "rawCategory": "personalities",
    "title": "Growing together: Liudmyla Zaruba has become the Head of the Talent Management department",
    "summary": "A new chapter for Liudmyla: leading Talent Management to support people, culture, and growth.",
    "cover": "https://cdn.prod.website-files.com/686d0fd099ee65617e107e24/69b0459d3c1edc369fad5067_Web%20cover%20person-7.jpg",
    "accentColor": "#4d2236",
    "readTime": "1 min",
